def max_product(arr, n):
    """Write a function to find the maximum product formed by multiplying numbers of an increasing subsequence of that array."""
    if not arr:
        return 0
    if n is None or n <= 0:
        return 0
    m = min(n, len(arr))
    if m <= 0:
        return 0
    a = list(arr[:m])
    max_ending = list(a)
    min_ending = list(a)
    best = max_ending[0]
    for i in range(1, m):
        for j in range(i):
            if a[j] < a[i]:
                prod_max = max_ending[j] * a[i]
                prod_min = min_ending[j] * a[i]
                if prod_max > max_ending[i]:
                    max_ending[i] = prod_max
                if prod_min > max_ending[i]:
                    max_ending[i] = prod_min
                if prod_max < min_ending[i]:
                    min_ending[i] = prod_max
                if prod_min < min_ending[i]:
                    min_ending[i] = prod_min
        if max_ending[i] > best:
            best = max_ending[i]
    return best
